from html import escape
from pathlib import Path

LOGO_PATH = Path(__file__).resolve().parent.parent / "assets" / "earthshine-logo.png"

def brand_mark():
    if LOGO_PATH.exists():
        return '<img class="earthshine-logo" src="/assets/earthshine-logo.png" alt="Earthshine Professional">'
    return '<div class="earthshine-wordmark">EARTHSHINE <span>PROFESSIONAL</span></div>'


